from common import *

def room():
    c1 = calc('c1', "Two metals, one doubled density", 'normal',
      "Zheludev, Jan 2024, Problem 2a, with numbers. Metals A and B are simple cubic with one atom per cell and the **same** cell volume, free-electron dispersion $E=\\hbar^2k^2/2m$. Metal A has conduction-electron density $n_A=8.47\\times10^{28}$ m$^{-3}$ (copper-like), metal B has $n_B=2n_A$. Fermi surface area $S=4\\pi k_F^2$, density of states $\\nu(\\epsilon_F)=3n/2\\epsilon_F$, $c_V=\\frac{\\pi^2}{3}\\nu(\\epsilon_F)k_B^2T$.",
      V('kB', nA=8.47e28),
      [step('kFA', "Fermi wavevector of A, $k_F=(3\\pi^2n)^{1/3}$, in Å$^{-1}$.", "(3*pi**2*nA)**(1/3)*1e-10", "A^-1", ["A^-1", "m^-1", "A^-2", "eV"], 0.02,
            "Each $\\vec k$ state occupies $(2\\pi)^3/V$ and holds 2 electrons: $n=\\frac{2}{(2\\pi)^3}\\frac{4\\pi}{3}k_F^3=k_F^3/3\\pi^2$."),
       step('EFA', "Fermi energy of A in eV.", "hbar**2*(3*pi**2*nA)**(2/3)/(2*me)/eV", "eV", ["eV", "meV", "K", "A^-1"], 0.02,
            "$\\epsilon_F=\\hbar^2k_F^2/2m=3.81\\,\\text{eV\\,Å}^2\\times k_F^2$."),
       step('EFB', "Fermi energy of B ($n_B=2n_A$) in eV.", "EFA*2**(2/3)", "eV", ["eV", "meV", "K", "A^-1"], 0.02,
            "$\\epsilon_F\\propto n^{2/3}$, so a factor $2^{2/3}=1.59$."),
       step('SAB', "Ratio of the Fermi surface areas $S_A/S_B$.", "(nA/(2*nA))**(2/3)", "dimensionless", ["dimensionless", "eV", "A^-2", "K"], 0.02,
            "$S\\propto k_F^2\\propto n^{2/3}$: $S_A/S_B=2^{-2/3}=0.63$ (key)."),
       step('nuAB', "Ratio of the densities of states at the Fermi energy $\\nu_A(\\epsilon_F)/\\nu_B(\\epsilon_F)$.", "(3*nA/(2*EFA))/(3*(2*nA)/(2*EFB))", "dimensionless", ["dimensionless", "eV", "A^-2", "K"], 0.02,
            "$\\nu(\\epsilon_F)=3n/2\\epsilon_F\\propto n^{1/3}$ (equivalently $\\propto m k_F$): $2^{-1/3}=0.79$."),
       step('cvAB', "Ratio of the electronic specific heats per volume at 10 K, $c_{V,A}/c_{V,B}$.", "nuAB", "dimensionless", ["dimensionless", "eV", "A^-2", "K"], 0.02,
            "$c_V=\\frac{\\pi^2}{3}\\nu(\\epsilon_F)k_B^2T$: the ratio is just the ratio of $\\nu(\\epsilon_F)$. Measuring $\\gamma$ measures the density of states."),
       step('cvA', "(Bonus) $c_{V,A}$ at 10 K in J m$^{-3}$ K$^{-1}$.", "pi**2/3*(3*nA/(2*EFA*eV))*kB**2*10", "J/(m^3 K)", ["J/(m^3 K)", "J/(m^3 K^2)", "J/K", "J/(m^3 K^4)"], 0.03,
            "$\\nu=1.13\\times10^{47}\\,{\\rm J^{-1}m^{-3}}$, $\\frac{\\pi^2}{3}\\nu k_B^2\\cdot10\\,{\\rm K}=7.1\\times10^2$ J m$^{-3}$K$^{-1}$, tiny compared with the Dulong–Petit $3.5\\times10^6$.", bonus=True)],
      70)

    c2 = calc('c2', "Is that electron gas degenerate?", 'fermi',
      "Quick fight, in the spirit of the HS20 multiple-choice question (m): a metal has an electron density of $5.00\\times10^{22}$ cm$^{-3}$. In the free-electron model at $T=0$, find the Fermi energy (the offered answers were 310 eV, 0.786 meV, 3.118 eV and 4.95 eV; derive, do not guess), then the Fermi temperature and the fraction of electrons that can be thermally excited at room temperature.",
      V('kB', n=5.0e28, T=300.0),
      [step('EF', "Fermi energy in eV.", "hbar**2*(3*pi**2*n)**(2/3)/(2*me)/eV", "eV", ["eV", "meV", "keV", "K"], 0.05,
            "Convert to SI first: $n=5.00\\times10^{28}$ m$^{-3}$. $k_F=1.14$ Å$^{-1}$, $\\epsilon_F=3.81\\times1.30=4.95$ eV. Always check units: densities in cm$^{-3}$ are a classic trap."),
       step('TF', "Fermi temperature $T_F=\\epsilon_F/k_B$ in K.", "EF*eV/kB", "K", ["K", "eV", "meV", "J"], 0.05,
            "$1\\,{\\rm eV}=11\\,604$ K. Metals have $T_F\\sim10^4$–$10^5$ K, far above room temperature."),
       step('frac', "Fraction of electrons that can be excited thermally at $T=300$ K, $\\approx k_BT/\\epsilon_F$.", "kB*T/(EF*eV)", "dimensionless", ["dimensionless", "K", "eV", "J"], 0.2,
            "Only electrons within $\\sim k_BT$ of $\\epsilon_F$ have empty states to go to: $\\sim0.5\\%$. This is why $c_V$ is far below Dulong–Petit and why $\\chi_{\\rm Pauli}$ is $T$-independent.", tolType='log')],
      30)

    c3 = calc('c3', "From free electrons to bands: gaps and a tight-binding mass", 'normal',
      "A 1D crystal with lattice constant $a=3.0$ Å. (i) Nearly free electrons: a periodic potential with Fourier component $U_G=0.5$ eV at the zone boundary. Near $k=\\pi/a$ the plane waves $k$ and $k-G$ ($G=2\\pi/a$) are degenerate and mix. (ii) Tight binding: $E(k)=E_i-A_i-2B_i\\cos(ka)$ with $B_i=1.0$ eV (HS20 MC (n)).",
      dict(a=3.0e-10, B=1.0, UG=0.5),
      [step('Ezb', "Free-electron energy at the zone boundary $k=\\pi/a$ in eV, $\\hbar^2(\\pi/a)^2/2m_e$.", "hbar**2*(pi/a)**2/(2*me)/eV", "eV", ["eV", "meV", "A^-1", "J"], 0.02,
            "$\\hbar^2/2m_e=3.81$ eV Å$^2$ and $(\\pi/a)^2=1.10$ Å$^{-2}$."),
       step('Eg', "Gap at the zone boundary: solve the $2\\times2$ problem $\\begin{vmatrix}\\epsilon_k-E&U_G\\\\U_G&\\epsilon_{k-G}-E\\end{vmatrix}=0$ at $k=\\pi/a$ (where $\\epsilon_k=\\epsilon_{k-G}$): $E_\\pm=\\epsilon\\pm|U_G|$. Give $E_g=E_+-E_-$ in eV.", "2*UG", "eV", ["eV", "meV", "A^-1", "J"], 0.02,
            "Degenerate perturbation theory with the matrix element $U_G=\\frac1a\\int U(x)e^{-iGx}dx$. The standing waves $\\cos(\\pi x/a)$ and $\\sin(\\pi x/a)$ pile up on / between the ions, hence the splitting $2|U_G|$ (script 3.2.2)."),
       step('W', "Tight-binding bandwidth $E_{\\max}-E_{\\min}$ for $E=E_i-A_i-2B\\cos ka$, in eV.", "4*B", "eV", ["eV", "meV", "A^-1", "J"], 0.02,
            "$\\cos$ runs from $-1$ to $1$: width $4B$. Larger hopping $B$ (more orbital overlap) gives wider bands."),
       step('mstar', "Effective mass at the band minimum $k=0$, $m^*=\\hbar^2\\big/\\big(\\partial^2E/\\partial k^2\\big)=\\hbar^2/(2Ba^2)$, in units of $m_e$.", "hbar**2/(2*B*eV*a**2)/me", "dimensionless", ["dimensionless", "kg", "eV", "A^-1"], 0.02,
            "$\\partial^2E/\\partial k^2|_0=2Ba^2$. So $m^*/m_e=3.81/(B[{\\rm eV}]\\,a^2[\\text{Å}^2])=0.42$: narrow bands (small $B$) mean heavy electrons. The key to the HS20 MC answer $\\hbar^2/(2B_ia^2)$.")],
      60)

    boss1 = boss('b1', "Boss: the band gap at the M point of a 2D lattice (exam problem)",
      dict(file="materials/solid-state/old-exams/HS20.pdf", where="Task 5 'Bandlücke am M-Punkt in einem 2D-Gitter' (13 pt, Ensslin practice exam HS20); solution: solutions/Einführung in die Festkörperphysik HS20 (Solution).pdf"),
      30,
      "Translated from the German exam. Do the whole derivation on paper, then enter the numbers for the game values.",
      ["We consider electrons in a square lattice in two dimensions. The periodic potential is $U(x,y)=4U_0\\cos\\!\\big(\\tfrac{2\\pi x}{a}\\big)\\cos\\!\\big(\\tfrac{2\\pi y}{a}\\big)$ with lattice constant $a$. You compute the band gap at the $M$ point $\\vec k_M=\\frac\\pi a(\\hat e_x+\\hat e_y)$.",
       "(a) [3 pt] Start from $H\\psi=\\big(-\\frac{\\hbar^2}{2m}\\nabla^2+U\\big)\\psi=E\\psi$ with $U=\\sum_{\\vec G}U_{\\vec G}e^{i\\vec G\\cdot\\vec r}$ and $\\psi=\\sum_{\\vec k}C_{\\vec k}e^{i\\vec k\\cdot\\vec r}$. Show that $\\big(\\frac{\\hbar^2k^2}{2m}-E\\big)C_{\\vec k}+\\sum_{\\vec G}U_{\\vec G}C_{\\vec k-\\vec G}=0$.",
       "(b) [3 pt] Determine the Fourier components $U_{\\vec G}$ (hint: write the cosines as exponentials).",
       "(c) [2 pt] Give the four reciprocal lattice points nearest to $\\vec k_M$.",
       "(d) [4 pt] Take $\\vec G_1=0$ and $\\vec G_2=\\frac{2\\pi}{a}(\\hat e_x+\\hat e_y)$, the only two coupled by $U$ here, set up the $2\\times2$ determinant and solve for $E_\\pm$ at $\\vec k_M$.",
       "(e) [1 pt] What is the band gap $E_g^{(M)}$?",
       "Game numbers: $a=4.0$ Å, $U_0=0.50$ eV."],
      [fa('E0', "(d) Free-electron energy at $M$, $\\hbar^2k_M^2/2m=\\hbar^2\\pi^2/(ma^2)$, in eV.", "hbar**2*pi**2/(me*a**2)/eV", dict(a=4.0e-10), 0.01),
       fa('Ep', "(d) $E_+$ at $M$ in eV.", "hbar**2*pi**2/(me*a**2)/eV+U0", dict(a=4.0e-10, U0=0.5), 0.01),
       fa('Em', "(d) $E_-$ at $M$ in eV.", "hbar**2*pi**2/(me*a**2)/eV-U0", dict(a=4.0e-10, U0=0.5), 0.01),
       fa('Eg', "(e) Gap $E_g^{(M)}=E_+-E_-$ in eV.", "2*U0", dict(U0=0.5), 0.01),
       fa('kM', "$|\\vec k_M|=\\sqrt2\\pi/a$ in Å$^{-1}$.", "sqrt(2)*pi/a*1e-10", dict(a=4.0e-10), 0.01)],
      ["(a) Insert both expansions: $\\sum_{\\vec k}\\frac{\\hbar^2k^2}{2m}C_{\\vec k}e^{i\\vec k\\cdot\\vec r}+\\sum_{\\vec k',\\vec G}U_{\\vec G}C_{\\vec k'}e^{i(\\vec k'+\\vec G)\\cdot\\vec r}=E\\sum_{\\vec k}C_{\\vec k}e^{i\\vec k\\cdot\\vec r}$; relabel $\\vec k'=\\vec k-\\vec G$ in the second sum; plane waves are linearly independent, so each coefficient of $e^{i\\vec k\\cdot\\vec r}$ vanishes.",
       "(b) $U=U_0\\big(e^{2\\pi ix/a}+e^{-2\\pi ix/a}\\big)\\big(e^{2\\pi iy/a}+e^{-2\\pi iy/a}\\big)$: four terms, so $U_{\\vec G}=U_0$ for $\\vec G=\\pm\\frac{2\\pi}a(1,1),\\ \\pm\\frac{2\\pi}a(1,-1)$, zero otherwise.",
       "(c) Nearest reciprocal lattice points: $0,\\ \\frac{2\\pi}a\\hat e_x,\\ \\frac{2\\pi}a\\hat e_y,\\ \\frac{2\\pi}a(\\hat e_x+\\hat e_y)$. The four are equidistant from $\\vec k_M$, $|\\vec k_M-\\vec G|=\\sqrt2\\pi/a$: four degenerate plane waves. $U$ only couples $0$ and $\\frac{2\\pi}a(1,1)$ (difference $\\vec G$ with $U_G=U_0$); $\\frac{2\\pi}a\\hat e_x$ and $\\frac{2\\pi}a\\hat e_y$ differ by $(1,-1)$, also coupled.",
       "(d) $\\det\\begin{pmatrix}\\hbar^2k_M^2/2m-E&U_0\\\\U_0&\\hbar^2k_M^2/2m-E\\end{pmatrix}=0\\Rightarrow E_\\pm=\\frac{\\hbar^2\\pi^2}{ma^2}\\pm U_0$.",
       "(e) $E_g^{(M)}=E_+-E_-=2U_0$.",
       "Connection: this is degenerate perturbation theory in a 2-dimensional degenerate subspace (QM sheet 14, Stark effect): the gap is twice the off-diagonal matrix element."],
      80)

    return dict(file='fermi-sea', id='ss-fermi-sea', region="Solid State Crystal Caverns", title="The Fermi Sea", course="solid-state",
      topics=["free-electron gas: k_F, E_F, S_F, DOS, C_V", "Pauli exclusion and degeneracy", "Bloch theorem", "nearly free electrons, band gap 2|U_G|", "tight binding, effective mass"],
      sources=[dict(file="materials/solid-state/old-exams/HS23.pdf", where="Problem 2a (a)-(c) (Zheludev, Jan 2024); solution (1)"),
               dict(file="materials/solid-state/old-exams/HS20.pdf", where="MC (m) Fermi energy of 5.00e22 cm^-3, MC (n) tight-binding mass, MC (o) 2D DOS, MC (p) Bloch theorem, Task 5 (13 pt, M-point gap)"),
               dict(file="materials/solid-state/scripts/Script-2026_2026-09-01.pdf", where="Ch. 3.1 (pp. 66–76 free electrons, Fermi–Dirac, C_V), 3.2 (pp. 77–87 Bloch, NFE, tight-binding)"),
               dict(file="notes/solid-state/03-electrons-and-transport.md", where="transcription, formulas and checks")],
      links=[dict(course="qm", room="tunneling-bridge", why="Free electrons are the QM particle in a box with $N\\to\\infty$: counting states with $(2\\pi)^3/V$ per $\\vec k$ and the Pauli principle. Nearly-free electrons are degenerate perturbation theory (sheet 14)."),
             dict(course="astro", room="stellar-forge", why="The same Fermi gas holds up white dwarfs: see the Degenerate Core room (Choudhuri §5.2-5.3).")],
      intro="Inside the caverns a sea of electrons fills every state up to the Fermi energy. Count the states, find the Fermi surface and the density of states, then switch on the lattice and watch gaps open where Bragg reflection mixes plane waves.",
      encounters=[c1, c2, c3, boss1])
